cd /home/user/RL_Study/report-gepa/runs/originals/song-repetition && python3 - <<'PY'
import json, pandas as pd, numpy as np
for fact in json.load(open('facts.json')):
    print('='*70)
    env={'pd':pd,'np':np}
    for var,path in fact['tables'].items():
        env[var]=pd.read_csv(path)
    print(eval(fact['code'], env))
    print('claim:', fact['claim'])
PY
